mapper.select:
SELECT te.mini_salary, te.course_salary, re.course_count, (re.course_count * te.course_salary + te.mini_salary) AS total_salary FROM business_teacher te JOIN ( SELECT COUNT(id) AS course_count FROM business_teacher_sign_records
AND teacher_id = #{coachId}
AND DATE_FORMAT(sign_time, '%Y-%m') = #{salaryTime}
) re WHERE te.id = #{coachId}
